INSERT INTO interaction_turn (turn_id, attempt_id, main_question_id, turn_order, turn_type, ai_question_text, transcript_text, audio_segment_url, ai_reasoning, created_at) VALUES
('d44277be-3b12-5cfb-b366-521a156067cd', '5b26920b-4806-55af-841e-78b8af621914', '9768f4d4-7e44-5af5-a674-f2a40e8ca424', 1, 'MAIN', 'Câu hỏi chính: hãy trình bày khái niệm và nêu ví dụ cụ thể.', 'Theo em, khái niệm này mô tả các thành phần và cách chúng hoạt động cùng nhau.', 'https://example.com/aiviva/audio/turn-1.mp3', 'AI đánh giá mức độ liên quan, độ đầy đủ và tính nhất quán của câu trả lời.', '2026-10-15 08:59:00+07'),
('b37cbe92-46ec-53cf-a462-b2b8da737c87', '5b26920b-4806-55af-841e-78b8af621914', 'cfd5c783-4ba4-5efa-9960-7e14c9d901e3', 2, 'FOLLOW_UP', 'Câu hỏi đào sâu: em có thể giải thích rõ hơn lập luận vừa nêu không?', 'Em sẽ phân tích yêu cầu trước, sau đó chọn giải pháp phù hợp và kiểm thử.', 'https://example.com/aiviva/audio/turn-2.mp3', 'AI đánh giá mức độ liên quan, độ đầy đủ và tính nhất quán của câu trả lời.', '2026-10-15 08:58:00+07'),
('18e74d5c-5250-502a-8af1-809636e3dc99', '5b26920b-4806-55af-841e-78b8af621914', 'e9d762e2-6638-5375-9b30-4acc1d10d7aa', 3, 'MAIN', 'Câu hỏi chính: hãy trình bày khái niệm và nêu ví dụ cụ thể.', 'Ví dụ thực tế giúp làm rõ sự khác nhau giữa lý thuyết và cách áp dụng.', 'https://example.com/aiviva/audio/turn-3.mp3', 'AI đánh giá mức độ liên quan, độ đầy đủ và tính nhất quán của câu trả lời.', '2026-10-15 08:57:00+07'),
('d26f4e6e-ae98-5dc9-a42d-0505dbaa9f4b', '5b26920b-4806-55af-841e-78b8af621914', '9768f4d4-7e44-5af5-a674-f2a40e8ca424', 4, 'FOLLOW_UP', 'Câu hỏi đào sâu: em có thể giải thích rõ hơn lập luận vừa nêu không?', 'Ưu điểm là dễ quản lý, tuy nhiên cần cân nhắc hiệu năng và khả năng mở rộng.', 'https://example.com/aiviva/audio/turn-4.mp3', 'AI đánh giá mức độ liên quan, độ đầy đủ và tính nhất quán của câu trả lời.', '2026-10-15 08:56:00+07'),
